import java.util.*;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    static final Map<String, String> owner = new HashMap<>(); // seat -> user
    static final ReentrantLock lock = new ReentrantLock();     // one lock per show

    static boolean hold(String user, String... seats) {
        lock.lock();
        try {
            for (String s : seats) if (owner.containsKey(s)) return false; // check all first
            for (String s : seats) owner.put(s, user);                     // then take all
            return true;
        } finally { lock.unlock(); }   // always unlock
    }

    public static void main(String[] args) {
        System.out.println("alice A1,A2 -> " + hold("alice", "A1", "A2"));
        System.out.println("bob   A2,A3 -> " + hold("bob", "A2", "A3"));
        System.out.println("bob   A3    -> " + hold("bob", "A3")); // A3 was not leaked
        System.out.println("owners: " + new TreeMap<>(owner));
    }
}

