map<string, string> owner;   // seat -> user
mutex lk;                    // one lock per show

bool hold(const string& user, vector<string> seats) {
    lock_guard<mutex> g(lk); // unlocks automatically at scope exit
    for (auto& s : seats) if (owner.count(s)) return false; // check all first
    for (auto& s : seats) owner[s] = user;                  // then take all
    return true;
}

