public class Main {
    enum Status { AVAILABLE, HELD }

    static class Seat {
        Status status = Status.AVAILABLE;
        long holdUntil = 0;   // minute at which the hold ends

        void hold(long now, long minutes) { status = Status.HELD; holdUntil = now + minutes; }

        // Lazy expiry: a HELD seat whose time has passed counts as free. No thread needed.
        boolean isFree(long now) {
            return status == Status.AVAILABLE || now >= holdUntil;
        }
    }

    public static void main(String[] args) {
        Seat seat = new Seat();
        seat.hold(0, 10);   // injected "clock": we pass the time in
        for (long now : new long[]{5, 9, 10, 11})
            System.out.println("t=" + now + " free=" + seat.isFree(now));
    }
}

