public class Main {
    // Split total paise among n people; the first (total % n) people get one extra paisa
    static long[] split(long total, int n) {
        long[] parts = new long[n];
        for (int i = 0; i < n; i++) parts[i] = total / n + (i < total % n ? 1 : 0);
        return parts;
    }

