public class Main {
    public static void main(String[] args) {
        String[] names = {"A", "B", "C", "D"};
        int[] net = {-40, -15, 30, 25};   // net balance per person; negative = owes; sum = 0
        System.out.println("net: A=-40 B=-15 C=30 D=25");
        while (true) {
            int d = 0, c = 0;   // biggest debtor and biggest creditor
            for (int i = 0; i < net.length; i++) {
                if (net[i] < net[d]) d = i;
                if (net[i] > net[c]) c = i;
            }
            if (net[d] == 0) break;
            int pay = Math.min(-net[d], net[c]);   // this step zeroes at least one person
            System.out.println(names[d] + " pays " + names[c] + " " + pay);
            net[d] += pay;
            net[c] -= pay;
        }
    }
}

