import java.util.*;

public class Main {
    interface SplitStrategy { long[] split(long[] prices, String[] sharers); }   // result per user A,B,C

    // Split an amount among the given users in exact paise (first users get the remainder)
    static void share(long[] out, long amount, String users) {
        for (int i = 0; i < users.length(); i++)
            out[users.charAt(i) - 'A'] += amount / users.length() + (i < amount % users.length() ? 1 : 0);
    }

    public static void main(String[] args) {
        Map<String, SplitStrategy> registry = new LinkedHashMap<>();   // type name -> strategy
        registry.put("EQUAL", (prices, sharers) -> {
            long[] out = new long[3];
            long total = 0;
            for (long p : prices) total += p;
            share(out, total, "ABC");
            return out;
        });
        registry.put("ITEMS", (prices, sharers) -> {   // new type: nothing else changes (Open/Closed)
            long[] out = new long[3];
            for (int i = 0; i < prices.length; i++) share(out, prices[i], sharers[i]);
            return out;
        });
        long[] prices = {60000, 5000};          // pizza, soda in paise
        String[] sharers = {"ABC", "AB"};       // who shared each item
        for (String type : registry.keySet())
            System.out.println(type + " -> " + Arrays.toString(registry.get(type).split(prices, sharers)));
    }
}

