        var registry = new List<KeyValuePair<string, Strategy>>();   // type name -> strategy
        registry.Add(new KeyValuePair<string, Strategy>("EQUAL", (prices, sharers) =>
        {
            var o = new long[3];
            long total = 0;
            foreach (long p in prices) total += p;
            Share(o, total, "ABC");
            return o;
        }));
        registry.Add(new KeyValuePair<string, Strategy>("ITEMS", (prices, sharers) =>
        {   // new type: nothing else changes (Open/Closed)
            var o = new long[3];
            for (int i = 0; i < prices.Length; i++) Share(o, prices[i], sharers[i]);
            return o;
        }));
        long[] pr = { 60000, 5000 };            // pizza, soda in paise
        string[] sh = { "ABC", "AB" };          // who shared each item
        foreach (var kv in registry)
            Console.WriteLine(kv.Key + " -> [" + string.Join(", ", kv.Value(pr, sh)) + "]");
    }
}

