    static class TieredCapped implements FinePolicy {
        public int fine(int d, int price) {
            int f = Math.min(d, 7) * 2 + Math.max(d - 7, 0) * 5;
            return Math.min(f, price);
        }
    }

    public static void main(String[] args) {
        FinePolicy[] policies = {new Flat(), new TieredCapped()};
        String[] names = {"Flat", "TieredCapped"};
        int[] days = {3, 10, 40};
        for (int i = 0; i < policies.length; i++)   // the caller only knows the interface
            for (int d : days)
                System.out.println(names[i] + " days=" + d + " fine=" + policies[i].fine(d, 150));
    }
}

